-- SWRD v1.2 change archive.
--
-- An UNLINKED record of every row the v1.2 corrections removed or changed. No
-- foreign keys, no triggers and no views reference these tables, so they cannot
-- constrain, cascade, or affect any query against swrd.*. They exist so the
-- prior state survives inside the database itself -- independent of git, of the
-- rollback .sql files, and of any provider backup.
--
-- They carry everything a reversal needs, including created_at, which a plain
-- re-insert would otherwise silently reset to now().

begin;

create schema if not exists swrd_archive;
comment on schema swrd_archive is
  'Pre-correction state for applied data fixes. Unlinked: no FKs into swrd.*';

drop table if exists swrd_archive.removed_paper_authors_v1_2;
create table swrd_archive.removed_paper_authors_v1_2 (
  paper_id int not null, author_id int not null, "position" int,
  is_corresponding boolean, created_at timestamp,
  fix text not null, issue text not null,
  archived_at timestamptz not null default now());
comment on table swrd_archive.removed_paper_authors_v1_2 is
  'The 7,756 duplicate authorship credits deleted in v1.2 (issue #6), exactly as they stood.';
